-- Called once per signed-in manager. Deterministic IDs make repeated calls safe.
create function public.seed_demo_data() returns void language plpgsql security invoker set search_path=public as $$
declare item jsonb; actor uuid := auth.uid();
begin
 if actor is null then raise exception 'Sign in to load example data'; end if;
 for item in select * from jsonb_array_elements('[{"id": "00000000-0000-0000-0000-000000000001", "name": "The Maplewood", "address": "Demo address 1 (fictional)"}, {"id": "00000000-0000-0000-0000-000000000002", "name": "Oak & Willow", "address": "Demo address 2 (fictional)"}, {"id": "00000000-0000-0000-0000-000000000003", "name": "Parkside Residences", "address": "Demo address 3 (fictional)"}]'::jsonb) loop
 insert into public.properties (id,name,address) values (md5(actor::text || (item->>'id'))::uuid,item->>'name',item->>'address') on conflict do nothing;
 end loop;
 for item in select * from jsonb_array_elements('[{"id": "00000000-0000-0000-0000-00000000000b", "name": "Demo Tenant Olivia", "email": "demo-tenant-1@example.com", "property_id": "00000000-0000-0000-0000-000000000001"}, {"id": "00000000-0000-0000-0000-00000000000c", "name": "Demo Tenant Phoenix", "email": "demo-tenant-2@example.com", "property_id": "00000000-0000-0000-0000-000000000002"}, {"id": "00000000-0000-0000-0000-00000000000d", "name": "Demo Tenant Lana", "email": "demo-tenant-3@example.com", "property_id": "00000000-0000-0000-0000-000000000003"}, {"id": "00000000-0000-0000-0000-00000000000e", "name": "Demo Tenant Demi", "email": "demo-tenant-4@example.com", "property_id": "00000000-0000-0000-0000-000000000001"}, {"id": "00000000-0000-0000-0000-00000000000f", "name": "Demo Tenant Drew", "email": "demo-tenant-5@example.com", "property_id": "00000000-0000-0000-0000-000000000002"}]'::jsonb) loop
 insert into public.tenants (id,name,email,property_id) values (md5(actor::text || (item->>'id'))::uuid,item->>'name',item->>'email',md5(actor::text || (item->>'property_id'))::uuid) on conflict do nothing;
 end loop;
 for item in select * from jsonb_array_elements('[{"id": "00000000-0000-0000-0000-0000000000c9", "keyword": "leak", "category": "Maintenance"}, {"id": "00000000-0000-0000-0000-0000000000ca", "keyword": "heating", "category": "Maintenance"}, {"id": "00000000-0000-0000-0000-0000000000cb", "keyword": "rent", "category": "Payment"}, {"id": "00000000-0000-0000-0000-0000000000cc", "keyword": "emergency", "category": "Urgent"}, {"id": "00000000-0000-0000-0000-0000000000cd", "keyword": "repair", "category": "Maintenance"}]'::jsonb) loop
 insert into public.rules (id,keyword,category) values (md5(actor::text || (item->>'id'))::uuid,item->>'keyword',(item->>'category')::public.message_category) on conflict do nothing;
 end loop;
 for item in select * from jsonb_array_elements('[{"id": "00000000-0000-0000-0000-000000000065", "tenant_id": "00000000-0000-0000-0000-00000000000b", "property_id": "00000000-0000-0000-0000-000000000001", "source": "SMS", "content": "Hi! There\u2019s a leak under the kitchen sink. It seems to be getting worse \u2014 could someone come take a look?", "category": "Maintenance", "status": "Open", "created_at": "2026-09-08T10:42:00Z"}, {"id": "00000000-0000-0000-0000-000000000066", "tenant_id": "00000000-0000-0000-0000-00000000000c", "property_id": "00000000-0000-0000-0000-000000000002", "source": "Email", "content": "Quick question about rent for this month. Can you confirm the bank details are still the same?", "category": "Payment", "status": "Open", "created_at": "2026-09-08T09:18:00Z"}, {"id": "00000000-0000-0000-0000-000000000067", "tenant_id": "00000000-0000-0000-0000-00000000000d", "property_id": "00000000-0000-0000-0000-000000000003", "source": "WhatsApp", "content": "The heating in my apartment hasn\u2019t been working since last night. Could you send someone over?", "category": "Maintenance", "status": "Open", "created_at": "2026-09-08T08:05:00Z"}, {"id": "00000000-0000-0000-0000-000000000068", "tenant_id": "00000000-0000-0000-0000-00000000000e", "property_id": "00000000-0000-0000-0000-000000000001", "source": "SMS", "content": "Emergency: there\u2019s water coming through the ceiling in the hallway. Please call me as soon as possible.", "category": "Urgent", "status": "Open", "created_at": "2026-09-08T07:00:00Z"}, {"id": "00000000-0000-0000-0000-000000000069", "tenant_id": "00000000-0000-0000-0000-00000000000f", "property_id": "00000000-0000-0000-0000-000000000002", "source": "Email", "content": "Hi, I\u2019m expecting a large delivery on Friday. Is it okay for the courier to leave it in the lobby?", "category": "General", "status": "Open", "created_at": "2026-09-08T06:45:00Z"}, {"id": "00000000-0000-0000-0000-00000000006a", "tenant_id": "00000000-0000-0000-0000-00000000000b", "property_id": "00000000-0000-0000-0000-000000000001", "source": "Email", "content": "Just sent over this month\u2019s rent payment. Please let me know when it arrives. Thanks!", "category": "Payment", "status": "Resolved", "created_at": "2026-09-07T10:42:00Z"}, {"id": "00000000-0000-0000-0000-00000000006b", "tenant_id": "00000000-0000-0000-0000-00000000000d", "property_id": "00000000-0000-0000-0000-000000000003", "source": "SMS", "content": "The light on the second-floor landing keeps flickering. Would you be able to have it checked?", "category": "Maintenance", "status": "Open", "created_at": "2026-09-07T09:18:00Z"}, {"id": "00000000-0000-0000-0000-00000000006c", "tenant_id": "00000000-0000-0000-0000-00000000000c", "property_id": "00000000-0000-0000-0000-000000000002", "source": "WhatsApp", "content": "Thanks for arranging the repair so quickly. The kitchen tap is working perfectly now!", "category": "Maintenance", "status": "Resolved", "created_at": "2026-09-07T08:05:00Z"}, {"id": "00000000-0000-0000-0000-00000000006d", "tenant_id": "00000000-0000-0000-0000-00000000000e", "property_id": "00000000-0000-0000-0000-000000000001", "source": "Email", "content": "I\u2019d like to renew my lease when it ends in November. What are the next steps?", "category": "General", "status": "Open", "created_at": "2026-09-07T07:00:00Z"}, {"id": "00000000-0000-0000-0000-00000000006e", "tenant_id": "00000000-0000-0000-0000-00000000000f", "property_id": "00000000-0000-0000-0000-000000000002", "source": "SMS", "content": "The front door lock is sticking again. I had a hard time getting in this morning.", "category": "Maintenance", "status": "Open", "created_at": "2026-09-07T06:45:00Z"}, {"id": "00000000-0000-0000-0000-00000000006f", "tenant_id": "00000000-0000-0000-0000-00000000000d", "property_id": "00000000-0000-0000-0000-000000000003", "source": "Email", "content": "Could you send me a receipt for my last rent payment when you get a chance?", "category": "Payment", "status": "Resolved", "created_at": "2026-09-07T10:42:00Z"}, {"id": "00000000-0000-0000-0000-000000000070", "tenant_id": "00000000-0000-0000-0000-00000000000b", "property_id": "00000000-0000-0000-0000-000000000001", "source": "Other", "content": "Can I reserve the community room for a small gathering next Saturday afternoon?", "category": "General", "status": "Resolved", "created_at": "2026-09-07T09:18:00Z"}]'::jsonb) loop
 insert into public.messages (id,tenant_id,property_id,source,content,category,status,created_at) values (md5(actor::text || (item->>'id'))::uuid,md5(actor::text || (item->>'tenant_id'))::uuid,md5(actor::text || (item->>'property_id'))::uuid,(item->>'source')::public.message_source,item->>'content',(item->>'category')::public.message_category,(item->>'status')::public.message_status,(item->>'created_at')::timestamptz) on conflict do nothing;
 -- Preserve the example's manually reviewed category.
 update public.messages set category=(item->>'category')::public.message_category where id=md5(actor::text || (item->>'id'))::uuid;
 end loop;
end $$;
revoke all on function public.seed_demo_data() from public, anon;
grant execute on function public.seed_demo_data() to authenticated;
